// ───────────────────────── zapis ─────────────────────────
foreach ($data as $tid => $d) {
    $term = get_term($tid, 'serie');
    if (!$term || is_wp_error($term)) { printf("!! term %d nie istnieje\n", $tid); continue; }

    // FAQ -> JSON. Gate: bez znaku " w tekscie (smart quotes lamia json_decode), z diakrytykami.
    foreach ($d['faq'] as $qa) {
        if (strpos($qa['q'] . $qa['a'], '"') !== false) { printf("!! %d: cudzysłów w FAQ — STOP\n", $tid); continue 2; }
    }
    $json = json_encode($d['faq'], JSON_UNESCAPED_UNICODE);
    if (json_decode($json, true) === null) { printf("!! %d: FAQ nie parsuje — STOP\n", $tid); continue; }
    if (!preg_match('/[ąćęłńóśźż]/u', $json)) { printf("!! %d: FAQ bez diakrytyk — STOP\n", $tid); continue; }
    if (!preg_match('/[ąćęłńóśźż]/u', $d['wiki']) || !preg_match('/[ąćęłńóśźż]/u', $d['lead'])) {
        printf("!! %d: wiki/lead bez diakrytyk — STOP\n", $tid); continue;
    }
    if (strpos($d['wiki'], '{{LISTINGS_BAR}}') === false) { printf("!! %d: brak {{LISTINGS_BAR}} — STOP\n", $tid); continue; }

    update_term_meta($tid, '_asiaauto_lead', $d['lead']);
    update_term_meta($tid, '_asiaauto_h1_suffix', $d['h1_suffix']);
    update_term_meta($tid, '_asiaauto_pl_availability', $d['pl_availability']);
    update_term_meta($tid, 'asiaauto_wiki_body', wp_kses_post($d['wiki']));
    update_term_meta($tid, 'asiaauto_faq_json', $json);
    update_term_meta($tid, '_asiaauto_seo_rework', 'v1-2026-07-27');
    clean_term_cache([$tid], 'serie');

    printf("OK #%d %-22s lead=%d zn. | wiki=%d zn. | faq=%d Q / %d zn.\n",
        $tid, $term->name, mb_strlen($d['lead']), mb_strlen($d['wiki']), count($d['faq']), mb_strlen($json));
}
